//! The six bases a craft can be planned on, compiled in.
//!
//! Each file in `data/` holds one base, generated by `data/gen_base.py` from its `.spec.json`, so a
//! base's index in its [`Data`] is always `0`. A file lists every influence's tags, so the item
//! level and the influences a base is offered with come from this table, not from the file.

use std::sync::OnceLock;

use crate::data::Data;
use crate::item::Influence;

/// One base file: the key the API names it by, how it is shown, where it came from, its contents,
/// and the item level and influences the craft planner offers it at.
pub struct BaseFile {
    pub key: &'static str,
    pub label: &'static str,
    /// The file's path in the crate, for error messages.
    pub path: &'static str,
    /// The file's contents.
    pub source: &'static str,
    pub item_level: u8,
    pub influences: &'static [Influence],
}

pub const BASES: [BaseFile; 6] = [
    BaseFile {
        key: "shield",
        label: "Supreme Spiked Shield",
        path: "data/shield.json",
        source: include_str!("../data/shield.json"),
        item_level: 87,
        influences: &[Influence::Shaper],
    },
    BaseFile {
        key: "flask",
        label: "Quicksilver Flask",
        path: "data/flask.json",
        source: include_str!("../data/flask.json"),
        item_level: 86,
        influences: &[],
    },
    BaseFile {
        key: "boots-hunter",
        label: "Two-Toned Boots (Hunter)",
        path: "data/boots.json",
        source: include_str!("../data/boots.json"),
        item_level: 86,
        influences: &[Influence::Hunter],
    },
    BaseFile {
        key: "boots-redeemer",
        label: "Two-Toned Boots (Redeemer)",
        path: "data/redeemer-boots.json",
        source: include_str!("../data/redeemer-boots.json"),
        item_level: 86,
        influences: &[Influence::Redeemer],
    },
    BaseFile {
        key: "jewel",
        label: "Viridian Jewel",
        path: "data/jewel.json",
        source: include_str!("../data/jewel.json"),
        item_level: 83,
        influences: &[],
    },
    BaseFile {
        key: "crown",
        label: "Archdemon Crown",
        path: "data/crown.json",
        source: include_str!("../data/crown.json"),
        item_level: 86,
        influences: &[Influence::Shaper],
    },
];

/// The base file with this key.
pub fn find(key: &str) -> Option<&'static BaseFile> {
    BASES.iter().find(|base| base.key == key)
}

/// The base's data, parsed once.
pub fn data(key: &str) -> Result<&'static Data, String> {
    static PARSED: [OnceLock<Result<Data, String>>; 6] = [const { OnceLock::new() }; 6];
    let at = BASES
        .iter()
        .position(|base| base.key == key)
        .ok_or_else(|| format!("unknown base \"{key}\""))?;
    let base = &BASES[at];
    PARSED[at]
        .get_or_init(|| Data::from_json(base.source).map_err(|e| format!("{}: {e}", base.path)))
        .as_ref()
        .map_err(Clone::clone)
}
